_Q, True)\n\n    q_block_start_idx = tl.load(query_start_len_ptr +\n                                seq_idx) // BLOCK_Q + seq_idx\n\n    q_block_local_idx = q_block_global_idx - q_block_start_idx\n\n    cur_batch_in_all_start_index = tl.load(query_start_len_ptr + seq_idx)\n    cur_batch_in_all_stop_index = tl.load(query_start_len_ptr + seq_idx + 1)\n\n    cur_batch_query_len = cur_batch_in_all_stop_index \\\n        - cur_batch_in_all_start_index\n\n    if q_block_local_idx * BLOCK_Q >= cur_batch_query_len:\n        return\n\n    offs_m = tl.arange(0, BLOCK_M)\n    offs_d = tl.arange(0, HEAD_SIZE_PADDED)\n    query_pos = q_block_local_idx * BLOCK_Q + offs_m // num_queries_per_kv\n\n    query_offset_0 = cur_batch_in_all_start_index + query_pos\n    query_offset_1 = kv_head_idx * num_queries_per_kv + \\\n        offs_m % num_queries_per_kv\n    query_offset = (query_offset_0[:, None] * query_stride_0 +\n                    query_offset_1[:, None] * query_stride_1 + offs_d[None, :])\n\n    dim_mask = tl.where(offs_d < HEAD_SIZE, 1, 0).to(tl.int1)\n    query_mask_0 = tl.where(query_pos < cur_batch_query_len, 1, 0).to(tl.int1)\n    query_mask_1 = tl.where(query_offset_1 < num_query_heads, 1, 0).to(tl.int1)\n\n    # Q : (BLOCK_M, HEAD_SIZE_PADDED)\n    Q = tl.load(\n        query_ptr + query_offset,\n        mask=dim_mask[None, :] & query_mask_0[:, None] & query_mask_1[:, None],\n        other=0.0,\n    )\n\n    block_table_offset = seq_idx * block_table_stride\n\n    M = tl.full([BLOCK_M], float(\"-inf\"), dtype=tl.float32)\n    L = tl.full([BLOCK_M], 1.0, dtype=tl.float32)\n    acc = tl.zeros([BLOCK_M, HEAD_SIZE_PADDED], dtype=tl.float32)\n\n    # sequence len for this particular sequence\n    seq_len = tl.load(seq_lens_ptr + seq_idx)\n\n    # context length for this particular sequences\n    context_len = seq_len - cur_batch_query_len\n\n    # alibi slope for this head\n    if USE_ALIBI_SLOPES:\n        alibi_slope = tl.load(alibi_slopes_ptr + query_offset_1,\n                              mask=query_mask_1,\n                              other=0.0)\n\n    # compute the maximum key prefix it can attend to under causal masking\n    # for each query block\n    max_query_pos = tl.max(query_pos, axis=0)\n    max_kv_idx = context_len + max_query_pos\n    num_blocks = tl.minimum(cdiv_fn(seq_len, BLOCK_SIZE),\n                            cdiv_fn(max_kv_idx + 1, BLOCK_SIZE))\n\n    # iterate through tiles\n    for j in range(0, num_blocks):\n\n        physical_block_idx = tl.load(block_tables_ptr + block_table_offset + j)\n\n        offs_n = tl.arange(0, BLOCK_SIZE)\n\n        v_offset = (physical_block_idx * stride_v_cache_0 +\n                    kv_head_idx * stride_v_cache_2 +\n                    offs_d[None, :] * stride_v_cache_3 +\n                    offs_n[:, None] * stride_v_cache_1)\n\n        k_offset = (physical_block_idx * stride_k_cache_0 +\n                    kv_head_idx * stride_k_cache_2 +\n                    offs_d[:, None] * stride_k_cache_3 +\n                    offs_n[None, :] * stride_k_cache_1)\n\n        # K : (HEAD_SIZE, BLOCK_SIZE)\n        K_load = tl.load(key_cache_ptr + k_offset,\n                         mask=dim_mask[:, None],\n                         other=0.0)\n\n        if K_load.dtype.is_fp8():\n            if Q.dtype.is_fp8():\n                K = K_load\n            else:\n                K = (K_load.to(tl.float32) * tl.load(k_scale)).to(Q.dtype)\n        else:\n            K = K_load\n\n        # V : (BLOCK_SIZE, HEAD_SIZE)\n        V_load = tl.load(value_cache_ptr + v_offset,\n                         mask=dim_mask[None, :],\n                         other=0.0)\n\n        if V_load.dtype.is_fp8():\n            if Q.dtype.is_fp8():\n                V = V_load\n            else:\n                V = (V_load.to(tl.float32) * tl.load(v_scale)).to(Q.dtype)\n        else:\n            V = V_load\n\n        seq_offset = j * BLOCK_SIZE + offs_n\n\n        seq_mask = seq_offset[None, :] < context_len + query_pos[:, None] + 1\n\n        # S : (BLOCK_M, BLOCK_SIZE)\n        S = tl.zeros(shape=(BLOCK_M, BLOCK_SIZE), dtype=tl.float32)\n\n        S += scale * tl.dot(Q, K)\n\n        if USE_SOFTCAP:\n            S = apply_softcap(S, softcap)\n\n        S = tl.where(query_mask_1[:, None] & query_mask_0[:, None] & seq_mask,\n                     S, float(\"-inf\"))\n\n        if SLIDING_WINDOW > 0:\n            S = tl.where((context_len + query_pos[:, None] - seq_offset)\n                         < SLIDING_WINDOW, S, float(\"-inf\"))\n\n        if USE_ALIBI_SLOPES:\n            S += alibi_slope[:, None] * (seq_offset - context_len)\n\n        # compute running maximum\n        # m_j : (BLOCK_M,)\n        m_j = tl.maximum(M, tl.max(S, axis=1))\n        # For sliding window there's a chance the max is -inf due to masking of\n        # the entire row. In this case we need to set m_j 0 to avoid NaN\n        m_j = tl.where(m_j > float(\"-inf\"), m_j, 0.0)\n\n        # P : (BLOCK_M, BLOCK_SIZE)\n        P = tl.exp(S - m_j[:, None])\n\n        # l_j : (BLOCK_M,)\n        l_j = tl.sum(P, axis=1)\n\n        # alpha : (BLOCK_M, )\n        alpha = tl.exp(M - m_j)\n\n        # acc : (BLOCK_M, HEAD_SIZE_PADDED)\n        acc = acc * alpha[:, None]\n\n        # update constants\n        L = L * alpha + l_j\n        M = m_j\n\n        # acc : (BLOCK_M, HEAD_SIZE_PADDED)\n        acc += tl.dot(P.to(V.dtype), V)\n\n    # epilogue\n    acc = acc / L[:, None]\n\n    output_offset = (query_offset_0[:, None] * output_stride_0 +\n                     query_offset_1[:, None] * output_stride_1 +\n                     offs_d[None, :])\n\n    tl.store(\n        output_ptr + output_offset,\n        acc,\n        mask=dim_mask[None, :] & query_mask_0[:, None] & query_mask_1[:, None],\n    )"
    }
}
EOF
